// Hafta 1: Dijital giriş ve çıkış. Buton D7 ile GND arasında; dahili
// pull-up sayesinde ayrı direnç gerekmez.
const int BUTON = 7;
const int LED = 8;

void setup() {
  pinMode(BUTON, INPUT_PULLUP); // basılmadığında HIGH okunur
  pinMode(LED, OUTPUT);
}

void loop() {
  // Butona basınca pin GND'ye bağlanır ve LOW okunur.
  if (digitalRead(BUTON) == LOW) {
    digitalWrite(LED, HIGH); // basılı: LED'i yak
  } else {
    digitalWrite(LED, LOW);  // basılı değil: LED'i söndür
  }
}

