// Hafta 2: Analog okuma ve PWM.
const int POT = A0;
const int LED = 9; // ~ işaretli PWM pini

void setup() {
  Serial.begin(9600);
  pinMode(LED, OUTPUT);
}

void loop() {
  int deger = analogRead(POT); // 0 ile 1023 arası
  int parlaklik = map(deger, 0, 1023, 0, 255); // 0 ile 255 arasına çevir
  analogWrite(LED, parlaklik);

  Serial.print("Pot: ");
  Serial.print(deger);
  Serial.print("  PWM: ");
  Serial.println(parlaklik);
  delay(200);
}

