// Hafta 2: HC-SR04 ile mesafe ölçümü ve buzzer.
const int TRIG = 10;
const int ECHO = 11;
const int BUZZER = 6;

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  pinMode(BUZZER, OUTPUT);
}

long mesafeOlc() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); // 10 µs'lik tetik darbesi
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long sure = pulseIn(ECHO, HIGH, 30000); // yankının dönüş süresi (µs)
  long cm = sure / 58;                    // süreyi santimetreye çevir
  return cm;
}

void loop() {
  long cm = mesafeOlc();
  Serial.print("Mesafe: ");
  Serial.print(cm);
  Serial.println(" cm");

  // 0 cm "ölçülemedi" demek; 1 ile 14 cm arası çok yakın.
  if (cm > 0 && cm < 15) {
    digitalWrite(BUZZER, HIGH); // engel yakın: buzzer'ı öttür
  } else {
    digitalWrite(BUZZER, LOW);  // engel uzak: buzzer'ı sustur
  }
  delay(200);
}

dht11.code:
// Hafta 2: DHT11 ile sıcaklık ve nem.
#include <DHT.h>

DHT dht(4, DHT11); // DATA ucu D4'te, sensör DHT11

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  delay(2000); // DHT11 en fazla 2 saniyede bir okunabilir
  float nem = dht.readHumidity();
  float sicaklik = dht.readTemperature();

  // Okuma başarısızsa sayı yerine "nan" gelir.
  if (isnan(nem) || isnan(sicaklik)) {
    Serial.println("DHT11 okunamadı!");
    return; // loop'u burada bitir, baştan başla
  }

  Serial.print("Sıcaklık: ");
  Serial.print(sicaklik);
  Serial.print(" °C   Nem: %");
  Serial.println(nem);
}

