// Hafta 3: Sensör → karar → servo, üç ayrı fonksiyonla.
#include <Servo.h>

const int IR = 2;
const int CIZGI = HIGH; // KH-09 siyah çizgide HIGH veriyor (ölçerek bulduk)
Servo kol;

// Sensörü okur.
int oku() {
  int durum = digitalRead(IR);
  return durum;
}

// Okunan duruma göre servonun gideceği açıyı seçer.
int kararVer(int durum) {
  if (durum == CIZGI) {
    return 30;  // çizgide 30 derece
  } else {
    return 130; // açık zeminde 130 derece
  }
}

// Servoyu verilen açıya götürür.
void hareketEt(int aci) {
  kol.write(aci);
}

void setup() {
  pinMode(IR, INPUT);
  kol.attach(9);
}

void loop() {
  int durum = oku();
  int aci = kararVer(durum);
  hareketEt(aci);
  delay(50);
}

