// Hafta 3: KH-09 IR sensörü ve RGB LED.
const int SENSOR = 2; // siyahta HIGH, beyazda LOW
const int R = 11;
const int G = 10;
const int B = 9;

// RGB LED'in üç rengine 0 ile 255 arası parlaklık verir.
void renk(int kirmizi, int yesil, int mavi) {
  analogWrite(R, kirmizi);
  analogWrite(G, yesil);
  analogWrite(B, mavi);
}

void setup() {
  pinMode(SENSOR, INPUT);
}

void loop() {
  if (digitalRead(SENSOR) == HIGH) {
    renk(255, 0, 0);  // çizgi üzerinde: kırmızı
  } else {
    renk(0, 180, 40); // beyaz zemin: yeşil
  }
}

