// Hafta 4: L298N ile iki DC motorun yön ve hız kontrolü.

// Sol motor
const int ENA = 5;  // hız (PWM)
const int IN1 = 8;  // yön
const int IN2 = 9;  // yön

// Sağ motor
const int ENB = 6;  // hız (PWM)
const int IN3 = 10; // yön
const int IN4 = 11; // yön

const int HIZ = 200; // 0 ile 255 arası

void solIleri() {
  digitalWrite(IN1, HIGH);
  digitalWrite(IN2, LOW);
  analogWrite(ENA, HIZ);
}

void solGeri() {
  digitalWrite(IN1, LOW);
  digitalWrite(IN2, HIGH);
  analogWrite(ENA, HIZ);
}

void solDur() {
  digitalWrite(IN1, LOW);
  digitalWrite(IN2, LOW);
  analogWrite(ENA, 0);
}

void sagIleri() {
  digitalWrite(IN3, HIGH);
  digitalWrite(IN4, LOW);
  analogWrite(ENB, HIZ);
}

void sagGeri() {
  digitalWrite(IN3, LOW);
  digitalWrite(IN4, HIGH);
  analogWrite(ENB, HIZ);
}

void sagDur() {
  digitalWrite(IN3, LOW);
  digitalWrite(IN4, LOW);
  analogWrite(ENB, 0);
}

void setup() {
  Serial.begin(9600);
  pinMode(ENA, OUTPUT);
  pinMode(IN1, OUTPUT);
  pinMode(IN2, OUTPUT);
  pinMode(ENB, OUTPUT);
  pinMode(IN3, OUTPUT);
  pinMode(IN4, OUTPUT);
}

void loop() {
  Serial.println("İleri");
  solIleri();
  sagIleri();
  delay(1500);

  Serial.println("Geri");
  solGeri();
  sagGeri();
  delay(1500);

  Serial.println("Sağa"); // sol ileri, sağ geri: yerinde sağa döner
  solIleri();
  sagGeri();
  delay(1000);

  Serial.println("Sola"); // sol geri, sağ ileri: yerinde sola döner
  solGeri();
  sagIleri();
  delay(1000);

  Serial.println("Dur");
  solDur();
  sagDur();
  delay(1000);
}
